def transform(grid):
    h,w=len(grid),len(grid[0])
    # Observed diagonals are encoded by r+c. Extend their repeated sequence;
    # find the shortest compatible period, then nearest-fill unobserved phases.
    marks={}
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v:
                marks[r+c]=v
    p=next((p for p in range(1,h+w+1) if all((a-b)%p or x==y for a,x in marks.items() for b,y in marks.items())),h+w)
    vals={a%p:v for a,v in marks.items()}
    for k in range(p):
        if k not in vals:
            q=min(vals,key=lambda q:(min((k-q)%p,(q-k)%p),q))
            vals[k]=vals[q]
    return [[vals[(r+c)%p] for c in range(w)] for r in range(h)]
